-- Video metadata and independent backup verification; media bytes remain outside D1.
CREATE TABLE IF NOT EXISTS video_assets(id TEXT PRIMARY KEY NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id TEXT REFERENCES posts(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'awaiting_upload' CHECK(status IN ('awaiting_upload','uploaded','processing','ready','failed')),source_key TEXT NOT NULL UNIQUE,hls_key TEXT,thumbnail_key TEXT,duration_seconds REAL,source_bytes INTEGER NOT NULL,mime_type TEXT NOT NULL,width INTEGER,height INTEGER,failure_code TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_video_assets_owner_created ON video_assets(owner_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_video_assets_status ON video_assets(status,updated_at);
CREATE TABLE IF NOT EXISTS video_backup_jobs(id TEXT PRIMARY KEY NOT NULL,video_id TEXT NOT NULL REFERENCES video_assets(id) ON DELETE CASCADE,object_key TEXT NOT NULL,checksum_sha256 TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','copying','verified','failed')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(video_id,object_key));
INSERT OR IGNORE INTO cenpaya_migrations(version,migration_name) VALUES(58,'private_b2_video_pipeline_and_tigris_backup');
